INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (36545, N'8.S.B', N'Is there a method in place where notifications are recieved about cyber threats that are actively targeting other organizations (such as joining an information sharing and analysis organization (ISAO) or information sharing and analysis center(ISAC))?
