INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (36547, N'10.S.A', N'Are cybersecurity policies established and supplemented with procedures that enable said policies to be implemented?
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (36548, N'1.S.A.1', N'Does the organization avoid “free” or “consumer” e-mail systems for business? ', N'<p class="MsoNormal"><b><i>Consider controls 1.S.A.1 - 1.S.A.7 to enhance the security posture of your e-mail system. Check with your e-mail service provider to ensure that these controls are in place and enabled.</i></b></p><p class="MsoNormal">Such systems are not approved to store, process, or transmit PHI.&#160; We recommend contracting with a service provider that caters to the health care or public health sector.<b><i><br></i></b></p><p class="MsoNormal"><b><i><br></i></b></p><p class="MsoNormal"><b>PR.DS-2:&#160;</b><i>Data-in-transit is protected&#160; &#160; &#160;<b> &#160; &#160; &#160;&#160;</b></i></p>&#10;&#10;<p class="MsoNormal"><span>Information and records (data) are managed&#10;consistent with the organization&#8217;s risk strategy to protect the confidentiality,&#10;integrity, and availability of information.</span><br></p><p class="MsoNormal"><b>PR.IP-1:&#160;</b><span><i>A baseline configuration of information technology/industrial control systems is created and maintained incorporating security principles (e.g. concept of least functionality)</i></span><br></p>&#10;&#10;<p class="MsoNormal"><span>Security&#10;policies (that address purpose, scope, roles, responsibilities, management&#10;commitment, and coordination among organizational entities), processes, and&#10;procedures are maintained and used to manage protection of information systems&#10;and assets.</span><br></p><p class="MsoNormal"><b>PR.AC-7:&#160;</b><span><i>Users, devices, and other assets are authenticated (e.g., single-factor, multifactor) commensurate with the risk of the transaction (e.g., individuals&#8217; security and privacy risks and other organizational risks)</i></span><br></p>&#10;&#10;<p class="MsoNormal"><span>Access to physical and logical assets and associated facilities is limited to&#10;authorized users, processes, and devices, and is managed consistent with the&#10;assessed risk of unauthorized access to authorized activities and transactions.</span><br></p>&#10;&#10;<p class="MsoNormal"><br></p>', N'E-mail Protection Systems', N'E-mail System Configuration  ', NULL, NULL, N'HHS405d', NULL, NULL, NULL, 60, NULL, NULL)
