UPDATE [dbo].[HYDRO_DATA] SET [Action_Item_Description]=N'Does the hydro facility install UPS in their electrical network to reduce the risk of power supply distortion? Note UPS is required for critical panel where short harmonic disruption effect the panel equipment.', [Action_Items]=N'The second power supply will protect against hardware failure, but not power failure. However, a UPS can protect the system if power is lost. A UPS usually provides 30 to 60 minutes of temporary backup power to permit a graceful shutdown. A UPS can also protect against power fluctuations by filtering incoming power and providing a steady power source.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       ', [Severity]=1, [Sequence]=107 WHERE [Mat_Option_Id] = 3757
UPDATE [dbo].[HYDRO_DATA] SET [Action_Item_Description]=N'Does the DC system have redundant battery banks, each with its own battery charger to ensure the continuous operation?', [Action_Items]=N'Develop a plan for constructing redundancies for critical system components based on prioritization and budget allocations                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ', [Severity]=1, [Sequence]=108 WHERE [Mat_Option_Id] = 3763
UPDATE [dbo].[HYDRO_DATA] SET [Action_Item_Description]=N'Are diverse supply chains used for mission-critical technical components?', [Action_Items]=N'Improve resiliency of supply chain by expanding network of providers for a better risk response and efficiency.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ', [Severity]=1, [Sequence]=109 WHERE [Mat_Option_Id] = 3970
UPDATE [dbo].[HYDRO_DATA] SET [Action_Item_Description]=N'Is there a process to verify supply chain integrity?', [Action_Items]=N'Implementing a supply chain integrity process can help intended material is not tampered with throughout the manufacturing and distribution process until received by the end user.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ', [Severity]=1, [Sequence]=110 WHERE [Mat_Option_Id] = 3973
